svg.script:
(function () {
  var mover = document.getElementById('mover');
  var clock = document.getElementById('clock');
  var x0 = null;
  function frame(ts) {
    if (x0 === null) x0 = ts;
    var t = (ts - x0) / 1000; // seconds
    var x = 210 + 200 * Math.sin(2 * Math.PI * 0.5 * t);
    mover.setAttribute('x', x.toFixed(2));
    clock.textContent = 't=' + t.toFixed(3);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
